changeSet.sql:
ALTER TABLE player_badge_showcase ENABLE ROW LEVEL SECURITY;

-- Anyone can read badge showcases (public profiles show badges)
CREATE POLICY "badge_showcase_select_all"
    ON player_badge_showcase FOR SELECT
    USING (true);

-- Players can manage their own badge showcase
CREATE POLICY "badge_showcase_insert_own"
    ON player_badge_showcase FOR INSERT
    WITH CHECK (
        player_id IN (
            SELECT id FROM player_profiles WHERE user_id = auth.uid()
        )
    );

CREATE POLICY "badge_showcase_update_own"
    ON player_badge_showcase FOR UPDATE
    USING (
        player_id IN (
            SELECT id FROM player_profiles WHERE user_id = auth.uid()
        )
    );

changeSet.rollback:
DROP POLICY IF EXISTS "badge_showcase_update_own" ON player_badge_showcase;
DROP POLICY IF EXISTS "badge_showcase_insert_own" ON player_badge_showcase;
DROP POLICY IF EXISTS "badge_showcase_select_all" ON player_badge_showcase;
